package main

import (
	"context"
	"crypto/tls"
	"crypto/x509"
	"fmt"
	"log"
	"net"
	"net/http"
	"os"
	"time"
)

type colorDevice interface {
	SetColor(ledColor) error
}

func newHTTPClient(config clientConfig) (*http.Client, error) {
	roots, err := x509.SystemCertPool()
	if err != nil {
		return nil, fmt.Errorf("load system CA pool: %w", err)
	}
	if roots == nil {
		roots = x509.NewCertPool()
	}
	if config.CAFile != "" {
		certificate, err := os.ReadFile(config.CAFile)
		if err != nil {
			return nil, fmt.Errorf("read ca_file: %w", err)
		}
		if !roots.AppendCertsFromPEM(certificate) {
			return nil, fmt.Errorf("ca_file contains no valid PEM certificates")
		}
	}
	transport := &http.Transport{
		DialContext:           (&net.Dialer{Timeout: 10 * time.Second, KeepAlive: 30 * time.Second}).DialContext,
		ForceAttemptHTTP2:     true,
		TLSClientConfig:       &tls.Config{MinVersion: tls.VersionTLS12, RootCAs: roots},
		TLSHandshakeTimeout:   10 * time.Second,
		ResponseHeaderTimeout: 10 * time.Second,
		IdleConnTimeout:       90 * time.Second,
	}
	return &http.Client{Transport: transport}, nil
}

func followGateway(ctx context.Context, config clientConfig, token string, client *http.Client, updates chan<- statusInput, logger *log.Logger) {
	delay := config.ReconnectMin
	for ctx.Err() == nil {
		receivedStatus := false
		err := consumeSSE(ctx, client, config.GatewayURL, token, config.StreamTimeout, func(input statusInput) {
			receivedStatus = true
			select {
			case updates <- input:
			case <-ctx.Done():
			}
		})
		if ctx.Err() != nil {
			return
		}
		select {
		case updates <- statusInput{}:
		case <-ctx.Done():
			return
		}
		if receivedStatus {
			delay = config.ReconnectMin
		}
		logger.Printf("gateway stream unavailable: %v; reconnecting in %s", err, delay)
		timer := time.NewTimer(delay)
		select {
		case <-ctx.Done():
			timer.Stop()
			return
		case <-timer.C:
		}
		if !receivedStatus {
			delay *= 2
			if delay > config.ReconnectMax {
				delay = config.ReconnectMax
			}
		}
	}
}

func driveIndicator(ctx context.Context, device colorDevice, activityHold time.Duration, updates <-chan statusInput) error {
	state := newIndicator(activityHold)
	lastInput := statusInput{}
	currentColor := ledColor(255)
	var timer *time.Timer
	var timerChannel <-chan time.Time

	stopTimer := func() {
		if timer == nil {
			return
		}
		if !timer.Stop() {
			select {
			case <-timer.C:
			default:
			}
		}
		timerChannel = nil
	}
	defer stopTimer()

	apply := func(now time.Time) error {
		color, next := state.observe(lastInput, now)
		if color != currentColor {
			if err := device.SetColor(color); err != nil {
				return err
			}
			currentColor = color
		}
		stopTimer()
		if !next.IsZero() {
			delay := time.Until(next)
			if delay < 0 {
				delay = 0
			}
			if timer == nil {
				timer = time.NewTimer(delay)
			} else {
				timer.Reset(delay)
			}
			timerChannel = timer.C
		}
		return nil
	}

	if err := apply(time.Now()); err != nil {
		return fmt.Errorf("set initial disconnected LED: %w", err)
	}
	for {
		select {
		case <-ctx.Done():
			if currentColor != colorOff {
				if err := device.SetColor(colorOff); err != nil {
					return fmt.Errorf("turn LED off during shutdown: %w", err)
				}
			}
			return nil
		case input := <-updates:
			lastInput = input
			if err := apply(time.Now()); err != nil {
				return fmt.Errorf("update LED: %w", err)
			}
		case now := <-timerChannel:
			if err := apply(now); err != nil {
				return fmt.Errorf("finish activity hold: %w", err)
			}
		}
	}
}
